:root {
  /* Colors */
  --color-linen-canvas: #fbfdf6;
  --color-paper-card: #f8f9f5;
  --color-sage-wash: #e9ede9;
  --color-carbon-pane: #1d2226;
  --color-forest-ink: #0a1d08;
  --color-moss-text: #2e4320;
  --color-sage-caption: #6b7860;
  --color-mist-ink: #d8e3dd;
  --color-moss-hairline: #2e43201a;
  --color-pebble-border: #c5ccb6;
  --color-forest-fill: #203b14;
  --color-pine-signal: #2b6b5e;
  --color-ember-signal: #991e4b;

  /* Typography — Font Families */
  --font-akkurat: "Akkurat", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-fragment-mono: "Fragment Mono", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-gt-america-mono: "GT America Mono", "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 9px;
  --leading-small: 1.11;
  --tracking-small: 0.09px;
  --text-caption: 11px;
  --leading-caption: 1.27;
  --tracking-caption: 1.1px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.23;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.0;
  --tracking-body: 0.28px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.44;
  --tracking-body-lg: 0px;
  --text-heading: 30px;
  --leading-heading: 1.16;
  --tracking-heading: -0.6px;
  --text-display: 53px;
  --leading-display: 1.21;
  --tracking-display: -2.12px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;

  /* Layout */
  --layout-page-max-width: 1280px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 8px;
  --layout-nav-height: 64px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-sm-2: 3px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 12px;
  --radius-2xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 12px;
  --radius-small-cards: 6px;
  --radius-buttons: 20px;
  --radius-pills: 9999px;
  --radius-tags: 9999px;
  --radius-badges: 3px;
  --radius-inner-tiles: 4px;
  --radius-small-elements: 2px;
  --radius-images: 6px;

  /* Shadows */
  --shadow-subtle: 0 0 0 1px rgba(52, 79, 49, 0.07);
  --shadow-sm: 0 0 0 1px #991e4b;
  --shadow-md: 0 0 0 1px rgba(52, 79, 49, 0.07), inset 0 1px 0 0 rgba(255, 255, 255, 0.9), 0 12px 32px -16px rgba(0, 0, 0, 0.2), 0 4px 10px -4px rgba(0, 0, 0, 0.12);
  --shadow-lg: 0 0 0 1px rgba(147, 175, 207, 0.1), inset 0 1px 0 0 rgba(255, 255, 255, 0.08), 0 16px 40px -18px rgba(0, 0, 0, 0.55), 0 5px 14px -6px rgba(0, 0, 0, 0.45);
  --shadow-xl: 0 24px 64px -48px rgba(117, 255, 188, 0.45);

  /* Surfaces */
  --surface-linen-canvas: #fbfdf6;
  --surface-sage-wash: #e9ede9;
  --surface-paper-card: #f8f9f5;
  --surface-carbon-pane: #1d2226;
}

